<style>
body{background:#06131b url("{{ asset('Imagenes/fondos/panel-profesor-codeplay.png') }}") center/cover fixed no-repeat!important;color:#edf9f6}body::before{content:"";position:fixed;inset:0;z-index:-1;background:linear-gradient(180deg,#0310188f,#041016e6),radial-gradient(circle at 50% 15%,transparent,#02090edb 88%)}.codeplay-navbar{background:#07151ce8!important;border-bottom:1px solid #79dabb32;backdrop-filter:blur(14px);box-shadow:0 10px 35px #0006}.teacher-page{min-height:calc(100vh - 70px);padding:clamp(8px,2vw,28px) 0 58px;font-size:17px;line-height:1.6}.teacher-page .container,.teacher-page .container-fluid{max-width:1480px}.teacher-frame{padding:clamp(20px,3vw,40px);border:1px solid #69c5aa59;border-radius:23px;background:linear-gradient(145deg,#071922f5,#0b2028ed);box-shadow:0 28px 75px #000a,inset 0 1px #d8fff319;backdrop-filter:blur(17px)}
.teacher-page-header{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;padding-bottom:25px;margin-bottom:28px;border-bottom:1px solid #405e65}.teacher-kicker{display:inline-flex;align-items:center;gap:8px;margin-bottom:9px;color:#f2c867;font-size:14px;font-weight:900;letter-spacing:.17em;text-transform:uppercase}.teacher-page-header h1{margin:0;font-family:Georgia,serif;font-size:clamp(31px,4vw,48px);font-weight:500}.teacher-page-header p{max-width:760px;margin:9px 0 0;color:#a9bec0;line-height:1.55}.teacher-actions{display:flex;justify-content:flex-end;gap:9px;flex-wrap:wrap}.teacher-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:48px;padding:12px 16px;border:1px solid #526f75;border-radius:10px;background:#102831;color:#eafaf6!important;text-decoration:none;font-size:15px;font-weight:800;line-height:1.1;transition:transform .2s,border-color .2s,background .2s}.teacher-btn:hover{transform:translateY(-2px);border-color:#75e2bf;background:#17363f}.teacher-btn-primary{border-color:#83efca;background:linear-gradient(110deg,#00d995,#19b989);color:#032018!important}.teacher-btn-gold{border-color:#e1c06e;background:#352f1c;color:#ffe399!important}.teacher-btn-danger{border-color:#a7555c;background:#321d23;color:#ffc8ca!important}.teacher-btn-small{min-height:42px;padding:9px 12px;font-size:14px}.teacher-btn svg,.teacher-btn i{flex:0 0 auto}
.guide-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:28px}.guide-step{display:flex;gap:12px;padding:14px;border:1px solid #35575e;border-radius:12px;background:#0c232bba}.guide-step b{flex:0 0 29px;width:29px;height:29px;display:grid;place-items:center;border-radius:9px;background:#00efa419;color:#6ce8c0}.guide-step strong,.guide-step span{display:block}.guide-step strong{font-size:16px}.guide-step span{margin-top:3px;color:#92aaac;font-size:14px;line-height:1.55}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:30px}.metric-card{padding:15px 17px;border:1px solid #36585f;border-radius:13px;background:#0c252e}.metric-card small{display:block;color:#b1c4c5;font-size:14px;text-transform:uppercase;letter-spacing:.08em}.metric-card strong{display:block;margin-top:3px;color:#70e7c1;font:500 28px Georgia,serif}
.section-block{margin-top:34px}.section-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:15px}.section-heading h2{margin:0;font-family:Georgia,serif;font-size:27px;font-weight:500}.section-heading p{margin:4px 0 0;color:#b1c2c3;font-size:15px}.section-tag{padding:6px 9px;border:1px solid #4c696f;border-radius:8px;color:#c4d3d4;font-size:14px}.teacher-card,.editor-card,.filter-panel{padding:19px;border:1px solid #395c63;border-radius:14px;background:linear-gradient(145deg,#0d2730e8,#091e27e8)}.teacher-card{height:100%}.bank-card-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.bank-card-head h3{margin:0;font-family:Georgia,serif;font-size:21px;font-weight:500}.bank-meta{margin:11px 0 0;color:#b5c6c7;font-size:15px;line-height:1.55}.empty-state{padding:26px;border:1px dashed #486a70;border-radius:13px;text-align:center;color:#9cb3b4;background:#0a202775}.help-note{display:flex;gap:10px;margin:14px 0;padding:12px 14px;border-left:3px solid #e7c765;border-radius:0 9px 9px 0;background:#302a186b;color:#eee1bd;font-size:15px;line-height:1.5}.help-note i{margin-top:2px;color:#f2c867}.teacher-page details{border:1px solid #35565d;border-radius:10px;background:#081d25}.teacher-page details>summary{padding:11px 13px;color:#7fe9c7;cursor:pointer;font-weight:800;font-size:15px}.teacher-page details[open]>summary{border-bottom:1px solid #35565d}.teacher-page details>form,.teacher-page details>.details-body{padding:13px}
.teacher-page .form-label{color:#e5f1ee;font-size:15px;font-weight:800}.teacher-page .form-control,.teacher-page .form-select{min-height:44px;border:1px solid #406469;border-radius:9px;background-color:#071a21;color:#f2fbf9;font-size:16px}.teacher-page .form-control::placeholder{color:#91abad;opacity:1}.teacher-page input[type="datetime-local"]::-webkit-calendar-picker-indicator{filter:invert(1) brightness(1.8);opacity:1;cursor:pointer}.teacher-page input[type="datetime-local"]::-webkit-calendar-picker-indicator:hover{filter:invert(1) brightness(2.4)}.teacher-page .form-control:focus,.teacher-page .form-select:focus{border-color:#62dfb9;box-shadow:0 0 0 3px #00efa418;background-color:#092129;color:#fff}.teacher-page .form-select option{background:#071a21}.teacher-page .form-check-input{border-color:#698286;background-color:#071a21}.teacher-page .form-check-input:checked{border-color:#36d9a3;background-color:#18bd87}.assignment-classes,.bank-checks{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px;padding:12px;border:1px solid #304e55;border-radius:10px;background:#061920}.assignment-classes .form-check,.bank-checks .form-check{padding:9px 10px 9px 34px;border-radius:8px;background:#0e2932;color:#dceae7}.teacher-page .table-responsive{border:1px solid #3b5a61;border-radius:13px;overflow-x:auto}.teacher-page .table{margin:0;font-size:15px;--bs-table-bg:#0b222b;--bs-table-striped-bg:#102b34;--bs-table-hover-bg:#17343d;--bs-table-color:#e9f5f2;--bs-table-border-color:#304e55}.teacher-page .table thead{--bs-table-bg:#15333c;color:#82e7c7}.teacher-page .table th{font-size:14px;letter-spacing:.05em;text-transform:uppercase}.teacher-page .table td{vertical-align:middle}.teacher-page .table small{color:#c0d0d1;font-size:14px}.status-badge{display:inline-flex;align-items:center;padding:5px 8px;border-radius:99px;font-size:14px;font-weight:900;text-transform:uppercase;letter-spacing:.05em}.status-success{background:#174b3c;color:#8ff1cc}.status-muted{background:#2c3d42;color:#c1ced0}.status-gold{background:#473a18;color:#f6d979}.action-explanation{color:#b4c5c6;font-size:14px}.teacher-page small{font-size:14px}.teacher-page .alert{font-size:15px;border-radius:11px;border-width:1px;background:#10242b;color:#eefaf7}
.teacher-confirm-dialog{width:min(590px,calc(100% - 28px));padding:26px;border:1px solid #69e0ba;border-radius:20px;background:linear-gradient(145deg,#0d2b34,#071a22);color:#eefaf7;box-shadow:0 34px 100px #000d}.teacher-confirm-dialog::backdrop{background:#020c11db;backdrop-filter:blur(7px)}.teacher-confirm-visual{display:flex;align-items:center;gap:16px}.teacher-confirm-visual>span{width:64px;height:64px;display:grid;place-items:center;border-radius:17px;background:linear-gradient(145deg,#ffd463,#ff777f);color:#2b1704;font-size:27px}.teacher-confirm-visual small{color:#f2c867;font-size:14px;font-weight:900;letter-spacing:.12em}.teacher-confirm-visual h2{margin:4px 0;font:500 29px Georgia,serif}.teacher-confirm-dialog>p{margin:20px 0;color:#c8d9d7;font-size:17px;line-height:1.6}.teacher-confirm-actions{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap}.teacher-confirm-actions form{margin:0}
@media(max-width:900px){.guide-strip,.metric-grid{grid-template-columns:1fr 1fr}.teacher-page-header{align-items:flex-start;flex-direction:column}.teacher-actions{justify-content:flex-start}}@media(max-width:575px){.teacher-frame{padding:18px 13px;border-radius:14px}.guide-strip,.metric-grid{grid-template-columns:1fr}.teacher-btn{width:100%}.teacher-actions{width:100%}.section-heading{align-items:flex-start;flex-direction:column}.bank-card-head{flex-direction:column}}
</style>
